def from_payload(cls, data, state):
    """
    Construct a response from the gateway payload.
    """

    # Reconstruct the component that was clicked
    clicked_component_id = data['data']['custom_id']
    clicked_component_payload = None
    for action_row in data['message'].get('components', list()):
        for component in action_row.get('components', list()):
            if component.get('custom_id', None) == clicked_component_id:
                clicked_component_payload = component
                break
        if clicked_component_payload is not None:
            break

    if clicked_component_payload is None:
        clicked_component_payload = {"custom_id": clicked_component_id}
    clicked_component_object = Component.from_dict(clicked_component_payload)

    # Make the response
    v = cls()
    v.data = data
    v._state = state
    v.component = clicked_component_object
    channel, guild = state._get_guild_channel(data)
    v.channel = channel
    v.guild = guild
    try:
        v.message = discord.Message(channel=channel, data=data['message'], state=state)
    except KeyError:
        v.message = discord.PartialMessage(channel=channel, id=int(data['message']['id']))
    if guild:
        v.user = discord.Member(data=data['member'], guild=guild, state=state)
    else:
        v.user = discord.User(data=data['user'], state=state)
    return v
